package Welcome;

public class stringFunctions {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		String s="sadashiv";
		System.out.println(s.length());
		char c=s.charAt(1);
		System.out.println(c);
		
		for(int i=0;i<s.length();i++) {
			System.out.print(s.charAt(i));
			System.out.print(" ");
		}
		

	}
      
}
